    public ReservationStatus confirm() {
        throw notAllowed("confirmar");
    }

    public ReservationStatus checkIn() {
        throw notAllowed("fazer check-in de");
    }

    public ReservationStatus checkOut() {
        throw notAllowed("fazer check-out de");
