        } catch (Exception e) {
            throw invalid("O corpo deve ser um JSON válido");
        }
        if (root == null || !root.isObject()) {
            throw invalid("O corpo deve ser um objeto JSON");
        }
        RequestParser p = new RequestParser(root);
        NewReservation r = new NewReservation(
