            return new ReservationView(r.id(), r.roomNumber(), r.guestName(), r.guestEmail(), r.guestCpf(),
                    r.checkIn(), r.checkOut(), r.guests(), r.ratePlan().name(), r.nights(), r.subtotal(),
                    r.discount(), r.total(), r.status().name(), r.amountPaid(), r.refund());
        }
    }

    private Api() {
    }

